      "sourceId": "investment-05",
      "number": 23,
      "stem": "老王正評估是否應投資 A 股票或 B 股票。已知 A 股票的預期報酬率為 10%，Beta 值為 1.2；B 股票的預期報酬率為 14%，Beta 值為 1.8。若預期市場投資組合的報酬率為 9%，無風險利率為 5%。你將建議老王投資哪一支股票？理由是什麼？",
