      "stem": "以下有關附條件交易的敘述，何者正確？ I、附條件交易依據自然人及法人身分差異而有不同的課稅制度 II、附賣回利率大於附買回利率 III、屬於貨幣市場工具 IV、以政府公債為主的標的",
