      "sourceId": "investment-05",
      "number": 32,
      "stem": "假設目前市場上的無風險利率等於 1%，而市場風險溢酬等於 3.5%，請問下列哪一檔股票沒有正確反映資本資產定價模型(CAPM)的評價？",
