      "subject": "investment",
      "sourceId": "investment-04",
      "number": 19,
      "stem": "已知一最適風險投資組合，其期望報酬率為 12%，標準差為 26%，若無風險利率為 5%，請問其最適(feasible)資本分配線(CAL)的斜率約為？",
