      "number": 23,
      "stem": "請問下列敘述何者為正確？ I.風險嫌惡的投資人會拒絕公平賽局(fair game)的投資機會 II.風險中立的投資人對風險性投資的判斷主要僅依據其期望報酬的高低來定 III.風險嫌惡的投資人對投資的判斷主要僅依據其風險的大小來定 IV.風險喜好的投資人會拒絕公平賽局的投資機會",
