      "session": 4,
      "subject": "investment",
      "sourceId": "investment-10",
      "number": 14,
      "stem": "張經理欲投資一檔債券，該債券目前的市值(市場價格加應計利息)為$10,500,000。由於自有資金有限，張經理決定與券商承作保證金交易(Margin Trading)，保證金金額為$900,000，附賣回利率為 3%，承作期間為三十天。若張經理在承作期間接到保證金追繳通知，最後決定終止交易。券商將標的債券賣出後得款$10,080,000，全部交易期間總共 15 天。試計算張經理由此次保證金交易所得之報酬率是多少？(利息以 Actual/360 計算，不考慮交易成本)",
