      "session": 4,
      "subject": "investment",
      "sourceId": "investment-07",
      "number": 19,
      "stem": "假設兩年期零息債券之面額為$1,000，發行時價格為$914，每年複利一次，試計算該債券發行時之殖利率約為多少？",
