      "year": 108,
      "session": 4,
      "subject": "investment",
      "sourceId": "investment-10",
      "number": 28,
      "stem": "假設目前市場投資組合期望報酬等於 12%，無風險利率等於 2%。某投資人目前持有市場價值 $20,000,000，β值為 0.9 的上市股票投資組合。該投資人擬利用近月臺股期貨(代號 TX)，經由槓桿效果將其投資組合期望報酬增加約一倍(即模擬正向兩倍基金)。若目前近月期貨成交價格為 11,000 點。在不考慮稅、保證金和交易成本下，試問他須交易多少口指數期貨契約？",
