      "stem": "當大華公司的資產報酬率高於舉債資金成本時增加其財務槓桿，在其他情況不變下，此項變動可能會增加大華公司的甲.β(系統風險)；乙.整個景氣循環期間的盈餘波動性；丙.股東權益報酬率；丁.股票價格",
