      "subject": "investment",
      "sourceId": "investment-09",
      "number": 5,
      "stem": "某乙期初有財富 \\(W=\\$1,000\\)，有一項風險性投資，一年後有 0.6 的機率賺到 40%，有 0.4 的機率賠 20%，如果他的財富效用函數是 \\(U(W)=\\sqrt{W}\\)，請計算他的預期期末財富效用 \\(E(U(W))\\)：",
