      "stem": "臺灣證券交易所股價指數期貨(臺股期貨)原始保證金為$90,000，維持保證金$69,000。投資者存入保證金$90,000，賣出 1 口臺股期貨，價位為 8,000。請問臺指期貨漲至 8,200 時，則投資人應補繳多少保證金？(不考慮手續費與稅)",
