      "year": 109,
      "session": 4,
      "subject": "investment",
      "sourceId": "investment-16",
      "number": 7,
      "stem": "有關由上而下投資策略(Top Down Strategy)的敘述，何者正確：甲.先由國內外總體經濟面著眼，再尋求各產業景氣狀況，最後依照公司因素進行選股；乙.不論總體環境及產業景氣好壞，若公司體質優良即進行投資；丙.資產配置受國別不同、產業景氣差異之影響程度較大",
