      "stem": "某公司投資甲、乙兩債券(均為每年付息一次)，甲債券市值600 萬，殖利率5%，存續期間(Duration) 2.1 年﹔以及乙債券市值 400 萬，殖利率8%，存續期間 5.4 年。請問該債券組合的價格存續期間 (Dollar Duration)最接近多少？",
