      "session": 3,
      "subject": "investment",
      "sourceId": "investment-04",
      "number": 23,
      "stem": "下列有關資本市場線(CML)的敘述，何者有誤？ I. CML 是從無風險利率(risk-free rate)到市場投資組合(market portfolio)的線。 II. CML 是可達到的最佳資本配置線(capital allocation line)。 III. CML 也稱為證券市場線(security market line)。 IV. CML 的風險衡量為標準差(standard deviation)。",
