      "subject": "investment",
      "sourceId": "investment-05",
      "number": 25,
      "stem": "已知無風險利率為6%，預期市場報酬率為15%，若您預期甲股票的 β 係數為 1.2 且將提供13% 的報酬率。請問：您應該採取下列何種投資策略？",
