      "stem": "關於投資者風險態度的敘述中，何者錯誤？甲.投資高風險資產的投資者是風險愛好者；乙.信仰「高風險、高報酬」者是風險規避者；丙.風險中立者當風險增加時，其所要求的邊際報酬率會不變；丁.風險規避者在風險增加時，其所要求的邊際報酬率會減少",
