      "stem": "兩家相同產業的公司，除股利政策外，其他方面都一樣。這兩家公司都預期明年每股盈餘為$6，不過 K 公司每年都將所賺得盈餘以現金股利發放給股東，而L 公司則是每年將 40%的盈餘保留下來，做為再投資之用，並賺取 10%的報酬。經股利折現模式估計 K 公司股價為$50，試估計 L 公司股價為多少﹖",
