      "stem": "某券商發行了一檔結構型債券(Structured Note)，發行價格為$90.09，約定一年後若標的股價(P1) 是高於目前價格(P0)時，此債券償還面額$100，否則償還金額等於$100 × (P1 / P0)。若不考慮信用風險，試問投資者持有該債券到期，理論上最佳與最差之報酬率分別為多少？",
