      "stem": "今日，1 美元的即期匯率 = 新臺幣 NT$32，並假設購買力平價(Purchasing Power Parity, PPP) 成立。預期未來 1 年美國的通貨膨脹率為 8%，台灣為 2%。某公司計畫從美國進口商品，並將在 1 年後需要支付$100 萬美元，則其在 1 年後約需要準備多少新台幣支付貨款：",
