      "stem": "楊過將財富的 40%投資於風險性資產，期望報酬率為 15%，變異數為 0.04；再將剩餘之 60% 投資於國庫券（無風險） ，且報酬率為6%。試問楊過投資組合之期望報酬率及標準差為何？",
