      "number": 15,
      "stem": "三星科技公司股票買權(call option)在 2023 年 12 月 2 日的價格為每股 2.45 美元，而當天三星的股價是 101.28 美元。已知該買權將於 2023 年 12 月 18 日到期、履約價格(exercise price)為 106 美元。若在 12 月 18 日時，三星股價漲到 110 美元，則投資人買進該買權之利潤或損失為多少？",
