      "session": 3,
      "subject": "investment",
      "sourceId": "investment-04",
      "number": 18,
      "stem": "已知 X、Y 兩種證券的標準差皆為 20%，共變數為 -1%，某投資人將手中現金的 40% 購買 X 證券，剩下的購買 Y 證券，則其投資組合之標準差為多少？",
