      "sessionId": "112Q3",
      "year": 112,
      "session": 3,
      "subject": "investment",
      "sourceId": "investment-09",
      "number": 19,
      "stem": "投資人持有資產、同時買進賣權(put option)，使下方風險鎖定在賣權履約價格的投資策略，稱為？",
