      "year": 112,
      "session": 3,
      "subject": "investment",
      "sourceId": "investment-05",
      "number": 20,
      "stem": "完全分散風險之投資組合 G，其β 值等於 1.5。若市場投資組合報酬標準差等於 20%，依據資本資產定價模式(CAPM)，試問投資組合 G 之報酬標準差應為多少？",
