      "stem": "當允許以無風險利率借貸時，投資者應選擇哪條資本配置線(Capital Asset Line, CAL)與效率前緣(efficient frontier )相結合？ I.報償波動比(reward-to-volatility ratio)最高；II.能最大化其效用；III.斜率最大；IV.斜率最小",
