      "year": 112,
      "session": 3,
      "subject": "investment",
      "sourceId": "investment-05",
      "number": 32,
      "stem": "下列有關證券市場線(Security Market Line, SML)的敘述，何者有誤？ I. SML 是描述單一資產或組合的期望報酬率與其系統性風險(即β 值)的關聯性 II. 個別資產的預期報酬率受到個別資產的風險( )之影響，其最主要就是與市場組合之共變數( )來決定 III. 當共變數( IV. 當共變數(",
