      "session": 1,
      "subject": "investment",
      "sourceId": "investment-10",
      "number": 14,
      "stem": "某投資者目前持有市場價值一千萬元，β 值為 1.3 的上市股票投資組合，其害怕短期間內，因股市大跌造成其所持有之上市股票市值大幅下滑，故進一步賣出近月小型臺指期貨(代號 MTX)進行避險，欲將所持有之投資組合 β 值降至 0.6。該指數期貨目前為 23,333 點，試問應賣出口數為多少﹖(不考慮稅、保證金和交易成本，所需口數四捨五入)",
