      "subject": "investment",
      "sourceId": "investment-07",
      "number": 15,
      "stem": "某公司於年初發行一檔五年期債券，到期時一次還本付息。該債券到期金額計算公式：到期金額 = 債券面額 × [1 + 95% × Max( S&P500 指數成長率 – 10%，0)]。試問該公司融資方式為發行零息債券，並同時：",
