      "session": 1,
      "subject": "investment",
      "sourceId": "investment-07",
      "number": 16,
      "stem": "假設完美的債券市場，甲債券為一年期零息政府公債和價格為$840，乙債券為兩年期零息政府公債和價格為$800，兩債券面額都為$1,000，依據利率期限結構之預期理論(Expectations Theory)，目前市場投資人預期一年後的一年期零息債券的殖利率約為多少？",
