      "number": 23,
      "stem": "某投資組合中包含 3 檔股票，已知此 3 檔股票的預期報酬率分別是 12%、15%與 9%，對應的權重分別是 35%、30%與 35%。請問該投資組合之預期報酬率為多少？",
