      "sessionId": "114Q2",
      "year": 114,
      "session": 2,
      "subject": "investment",
      "sourceId": "investment-04",
      "number": 24,
      "stem": "若投資人希望建立一個位於資本配置線(Capital Allocation Line, CAL)上最適風險性投資組合 (optimal risky portfolio)右側之投資組合，則必須：",
      "options": [
        "以無風險利率(risk-free rate)貸出(lend)部分資金",
        "以無風險利率借入(borrow)部分資金，並投資於最佳無風險投資組合(optimal riskless portfolio)",
        "僅投資於無風險證券(risk-free securities)",
        "以無風險利率(risk-free rate)借入部分資金、投資於最適風險性投資組合(optimal risky portfolio)，而且僅投資於風險性證券(risky securities)"
      ],
      "answer": [
        "D"
      ],
      "sourceIds": [
        "investment-04"
      ],
      "sourceRefs": [
        {
          "chapterId": "investment-04",
          "sectionIndex": 2
        }
      ]
