      "stem": "考量在一個單因子經濟(one-factor economy)之下，投資組合 A 在此因子上的β係數為 1.0，投資組合 B 在該因子上的β係數為 2.0。投資組合 A 與 B 的預期報酬率分別為 11%與 17%。已知無風險利率為 6%，且有套利機會。假設你投資$100,000 於無風險資產，$100,000 於投資組合 B，並賣空(sold short)$100,000 於投資組合 A。請問你從該策略獲得的預期效益為多少？",
