      "stem": "全友公司的負債/權益比為0.25，普通股的β為1.15，債務的β為0.3，市場風險溢酬為10%，且無風險利率為 6%，公司稅率為 35%。一切符合證券市場線（ SML）的假設。現在全友公司決定投資一項和普通股風險相同的投資計畫，其報酬率應至少為多少，才值得投資？",
