      "stem": "甲資產報酬率 5%，標準差 10%，乙資產報酬率 10%，標準差為 20%。原本全部投資甲資產，想要分配部分資金到乙資產上，請問甲與乙資產的相關係數在怎樣的臨界值以下才能可以降低投資標準差風險？",
