      "number": 25,
      "stem": "Treynor and Mazuy (1966) 建議使用如下方程式來評估基金的選股以及擇時能力：\\(R_P-R_f=\\alpha_P+\\beta_p(R_m-R_f)+\\gamma_p(R_m-R_f)^2\\)，下面描述何者為正確？",
