      "session": 2,
      "subject": "investment",
      "sourceId": "investment-03",
      "number": 6,
      "stem": "假設投資者只以期望報酬與標準差作為投資準則，有兩個報酬彼此獨立的風險資產甲與乙，它們期望報酬相同，標準差也相同，一個風險厭惡的投資者該如何資產分配？",
