      "session": 2,
      "subject": "investment",
      "sourceId": "investment-07",
      "number": 9,
      "stem": "假設投資期限為一年，市場中信用風險相同之一年期及兩年期平價債券的殖利率分別為 1.5%及 1.8%；在不考慮操作成本的情況下，若經理人想要成功的執行「駕馭殖利率曲線」(Riding the Yield Curve)策略，則一年後的一年期利率必須不超過：",
