      "subject": "investment",
      "sourceId": "investment-07",
      "number": 12,
      "stem": "依據下列資訊，試回答以下四題：假設完美的債券市場環境成立，現有甲、乙兩種零息政府公債，面額皆為$1,000。甲債券為一年期，目前市場價格為$900；乙債券為兩年期，目前市場價格為$850。現有丙債券為兩年期付息政府公債，面額$1,000，票面利率為 20%，每年末付息一次。試問丙債券在目前市場上的合理價格應為多少？",
