      "stem": "依據下列資訊，試回答以下四題：假設完美的債券市場環境成立，現有甲、乙兩種零息政府公債，面額皆為$1,000。甲債券為一年期，目前市場價格為$900；乙債券為兩年期，目前市場價格為$850。承上題，若目前市場投資人對未來短期利率水準趨勢的預期完全正確，則資產配置經理人此時應採取下列何種債券投資組合操作策略，以增加收益或減少損失？",
